  it('renders legacy logo when type is "developer"', async () => {
    const {root} = await newSpecPage({
      components: [Logo],
      html: '<clab-logo type="developer"></clab-logo>'
    });

    expect(root).toEqualHtml(`
      <clab-logo type="developer">
        <mock:shadow-root>
          <clab-legacy fillcolor="black" fillstyle="positive" size="100%" type="developer"></clab-legacy>
        </mock:shadow-root>
      </clab-logo>
    `);
  });

